<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import AppShell from '../components/AppShell.vue'
const form=reactive({displayName:'',email:'',password:''});const error=ref('');const loading=ref(false);const auth=useAuthStore();const router=useRouter()
async function submit(){loading.value=true;error.value='';try{await auth.register(form.email,form.displayName,form.password);await router.push('/')}catch(e:any){error.value=e.response?.data?.error?.message||'注册失败，请稍后重试'}finally{loading.value=false}}
</script>
<template><AppShell><section class="auth-page"><div class="auth-aside"><span class="eyebrow">BEGIN YOUR INQUIRY</span><h1>把好奇心<br/>变成历史问题</h1><p>创建学生账户，开始构建你的学习路径与史学能力图谱。</p></div><el-card class="auth-card" shadow="never"><span class="eyebrow">加入课程</span><h2>创建学生账户</h2><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form :model="form" label-position="top"><el-form-item label="姓名"><el-input v-model="form.displayName" autocomplete="name" placeholder="你的称呼"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" type="email" autocomplete="email" placeholder="name@university.edu"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password autocomplete="new-password" placeholder="至少 8 位"/></el-form-item><el-button class="form-submit" type="primary" :loading="loading" @click="submit">注册并开始学习</el-button></el-form><p class="form-foot">已有账户？ <RouterLink to="/login">立即登录</RouterLink></p></el-card></section></AppShell></template>
